// The source scene was centered by the importer. Lift both the visible model
// and its collider so the bunker's own concrete floor sits on physics y=0.
const COLLISION_CELL_SIZE = 3.5 * BUNKER_LAYOUT_SCALE;
const COLLISION_VERTICAL_CELL_SIZE = BUNKER_LAYOUT_SCALE;
const BASE_DOOR_CLEARANCES = [
  { min: [4.7, 0, -8.6], max: [6.1, 2.6, -6.1] },
  { min: [-6.3, 0, -8.6], max: [-4.9, 2.6, -6.1] },
  { min: [4.7, 0, 2.2], max: [6.1, 2.6, 4.7] },
  { min: [-6.3, 0, 2.2], max: [-4.9, 2.6, 4.7] },
  { min: [-1.4, 0, 14.8], max: [1.1, 2.6, 16.2] }
] as const;
const DOOR_CLEARANCES = BASE_DOOR_CLEARANCES.map(({ min, max }) => ({
  min: min.map((value) => value * BUNKER_LAYOUT_SCALE),
  max: max.map((value) => value * BUNKER_LAYOUT_SCALE)
}));

function buildBunkerCollisionSections(): WorldHull[] {
  const source = BUNKER_COLLISION_SOURCE[0]!;
  const sourceTriangles = source.triangles ?? [];
  const vertices = source.vertices.map(([x, y, z]) => [
    x * BUNKER_COLLISION_SCALE,
    (y + BUNKER_FLOOR_OFFSET) * BUNKER_COLLISION_SCALE,
    z * BUNKER_COLLISION_SCALE
  ] as const);
  const parents = Array.from({ length: vertices.length }, (_, index) => index);
  const find = (index: number): number => parents[index] === index ? index : (parents[index] = find(parents[index]!));
  const union = (first: number, second: number): void => {
    const firstRoot = find(first);
    const secondRoot = find(second);
    if (firstRoot !== secondRoot) parents[secondRoot] = firstRoot;
  };
  for (const triangle of sourceTriangles) {
    union(triangle[0], triangle[1]);
    union(triangle[1], triangle[2]);
  }

  const connected = new Map<number, Array<readonly [number, number, number]>>();
  for (const triangle of sourceTriangles) {
    const root = find(triangle[0]);
    const group = connected.get(root) ?? [];
    group.push(triangle);
    connected.set(root, group);
  }

  const triangleGroups: Array<Array<readonly [number, number, number]>> = [];
  const splitLocallyConnected = (
    triangles: Array<readonly [number, number, number]>
  ): Array<Array<readonly [number, number, number]>> => {
    const trianglesByVertex = new Map<number, number[]>();
    triangles.forEach((triangle, triangleIndex) => triangle.forEach((vertexIndex) => {
      const linked = trianglesByVertex.get(vertexIndex) ?? [];
      linked.push(triangleIndex);
      trianglesByVertex.set(vertexIndex, linked);
    }));
    const visited = new Set<number>();
    const groups: Array<Array<readonly [number, number, number]>> = [];
    for (let start = 0; start < triangles.length; start += 1) {
      if (visited.has(start)) continue;
      const group: Array<readonly [number, number, number]> = [];
      const queue = [start];
      visited.add(start);
      while (queue.length) {
        const triangleIndex = queue.pop()!;
        const triangle = triangles[triangleIndex]!;
        group.push(triangle);
        for (const vertexIndex of triangle) for (const linkedIndex of trianglesByVertex.get(vertexIndex) ?? []) {
          if (visited.has(linkedIndex)) continue;
          visited.add(linkedIndex);
          queue.push(linkedIndex);
        }
      }
      groups.push(group);
    }
    return groups;
  };
  for (const component of connected.values()) {
    const componentVertices = [...new Set(component.flat())].map((index) => vertices[index]!);
    const minX = Math.min(...componentVertices.map((vertex) => vertex[0]));
    const maxX = Math.max(...componentVertices.map((vertex) => vertex[0]));
    const minZ = Math.min(...componentVertices.map((vertex) => vertex[2]));
    const maxZ = Math.max(...componentVertices.map((vertex) => vertex[2]));
    if (Math.max(maxX - minX, maxZ - minZ) <= COLLISION_CELL_SIZE * 2) {
      triangleGroups.push(component);
      continue;
    }
    const cells = new Map<string, Array<readonly [number, number, number]>>();
    for (const triangle of component) {
      const points = triangle.map((index) => vertices[index]!);
      const centerX = points.reduce((sum, point) => sum + point[0], 0) / 3;
      const centerY = points.reduce((sum, point) => sum + point[1], 0) / 3;
      const centerZ = points.reduce((sum, point) => sum + point[2], 0) / 3;
      const key = `${Math.floor(centerX / COLLISION_CELL_SIZE)},${Math.floor(centerY / COLLISION_VERTICAL_CELL_SIZE)},${Math.floor(centerZ / COLLISION_CELL_SIZE)}`;
      const cell = cells.get(key) ?? [];
      cell.push(triangle);
      cells.set(key, cell);
    }
    for (const cell of cells.values()) triangleGroups.push(...splitLocallyConnected(cell));
  }

  const sections: WorldHull[] = [];
  for (const triangles of triangleGroups) {
    const remap = new Map<number, number>();
    const sectionVertices: Array<readonly [number, number, number]> = [];
    const sectionTriangles = triangles.map((triangle) => triangle.map((oldIndex) => {
      let newIndex = remap.get(oldIndex);
      if (newIndex === undefined) {
        newIndex = sectionVertices.length;
        remap.set(oldIndex, newIndex);
        sectionVertices.push(vertices[oldIndex]!);
      }
      return newIndex;
    }) as [number, number, number]);
    if (sectionVertices.length < 4) continue;
    const sectionMin = [0, 1, 2].map((axis) => Math.min(...sectionVertices.map((vertex) => vertex[axis]!)));
    const sectionMax = [0, 1, 2].map((axis) => Math.max(...sectionVertices.map((vertex) => vertex[axis]!)));
    const crossesDoorway = DOOR_CLEARANCES.some((clearance) => [0, 1, 2].every((axis) =>
      sectionMax[axis]! >= clearance.min[axis]! && sectionMin[axis]! <= clearance.max[axis]!
    ));
    if (crossesDoorway) continue;
    sections.push({
      id: `bunker-collision-${sections.length + 1}`,
      vertices: sectionVertices,
      triangles: sectionTriangles,
      color: source.color,
      kind: "hull",
      solid: true,
      visible: false,
      modelId: "bunker"
    });
  }
  return sections;
}

/** Local sections preserve the bunker's concave rooms instead of filling its footprint. */
export const GENERATED_WORLD_HULLS: readonly WorldHull[] = buildBunkerCollisionSections();
